using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Accounting.Abstractions;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;using OAS.Domain.Features.Employees.Entities;
namespace OAS.Application.Accounting.EmployeeAccounts.Commands.SetEmployeeAccountStatus;
public sealed class SetEmployeeAccountStatusCommandHandler(IRepository<EmployeeAccount,Guid> repository,IReadRepository<Employee,Guid> employees,ILinkedAccountingAccountProvisioningService linkedAccounts):IRequestHandler<SetEmployeeAccountStatusCommand>
{public async Task Handle(SetEmployeeAccountStatusCommand r,CancellationToken ct){var e=await repository.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EmployeeAccount),r.Id);byte[] rv;try{rv=Convert.FromBase64String(r.Request.RowVersion);}catch(FormatException ex){throw new ConcurrencyException("Employee account row version is invalid.",ex);}if(!e.RowVersion.SequenceEqual(rv))throw new ConcurrencyException("Employee account mapping was modified by another user.");var employee=await employees.GetByIdAsync(e.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),e.EmployeeId);if(r.Request.IsActive&&!employee.IsActive)throw new ConflictException("employee_inactive","Inactive employee cannot have an active accounting mapping.");e.SetActive(r.Request.IsActive);await linkedAccounts.SynchronizeAsync(e.AccountId,employee.DisplayName,e.IsActive,ct);repository.Update(e);}}
